from rich.highlighter import ReprHighlighter
import re

def test_url_highlighter():
    url = "https://example.com/~user"

    # Find the URL regex in ReprHighlighter.highlights
    url_regex = None
    for h in ReprHighlighter.highlights:
        if "url" in h and "http" in h:
            url_regex = h
            break

    if url_regex is None:
        raise AssertionError("URL regex not found in ReprHighlighter.highlights")

    print(f"Using regex: {url_regex}")
    match = re.search(url_regex, url)
    if match:
        print(f"Matched: {match.group('url')}")
        assert match.group('url') == url
    else:
        print("No match found")
        raise AssertionError("URL with tilde was not matched")

if __name__ == "__main__":
    test_url_highlighter()
